function load() {
  try {
    if (!globalThis?.localStorage) return null;
    const current = globalThis.localStorage.getItem(SAVE_KEY);
    if (current) return JSON.parse(current);
    const legacy = globalThis.localStorage.getItem(LEGACY_KEY);
    return legacy ? JSON.parse(legacy) : null;
  } catch { return null; }
}
function save(data) {
  try { if (globalThis?.localStorage) globalThis.localStorage.setItem(SAVE_KEY, JSON.stringify(data)); } catch {}
}
function routeById(id) { return ROUTES.find(r => r.id === id) || ROUTES[0]; }
function makeService(platform, routeId, sets = 1) {
  return { platform, routeId, phase: 'arriving', countdown: 2, delay: 0, hold: 0, onboard: 0, sets };
}
function trainCapacityFor(service, levels, stationLevel) {
  const base = 95 + Math.max(1, levels.train || 1) * 65 + Math.max(0, stationLevel - 4) * 22;
  return base * service.sets;
}

function HudTile({ label, children, wide }) {
  return <View style={[styles.hudTile,wide&&styles.hudTileWide]}><Text style={styles.hudLabel}>{label}</Text>{children}</View>;
}

function MiniPeople({ count, color = '#48a8ff', max = 16 }) {
  const shown = Math.min(max, Math.ceil(Math.max(0, count) / 5));
  return <View style={styles.peopleRow}>{Array.from({length:shown}).map((_,i)=><View key={i} style={styles.personMini}><View style={styles.personHead}/><View style={[styles.personBody,{backgroundColor:i%4===0?color:i%4===1?'#df7856':i%4===2?'#6d78a8':'#557f72'}]}/></View>)}</View>;
}

function MovingDot({ delay = 0, duration = 3000, color = '#f4c787', from, to, size = 6 }) {
  const p=useRef(new Animated.Value(0)).current;
  useEffect(()=>{
    const loop=Animated.loop(Animated.sequence([
      Animated.delay(delay),
      Animated.timing(p,{toValue:1,duration,easing:Easing.linear,useNativeDriver:true}),
      Animated.timing(p,{toValue:0,duration:0,useNativeDriver:true}),
    ]));
    loop.start();return()=>loop.stop();
  },[delay,duration,p]);
  return <Animated.View style={[styles.movingDot,{width:size,height:size,borderRadius:size/2,backgroundColor:color,transform:[{translateX:p.interpolate({inputRange:[0,1],outputRange:[from[0],to[0]]})},{translateY:p.interpolate({inputRange:[0,1],outputRange:[from[1],to[1]]})}],opacity:p.interpolate({inputRange:[0,.08,.9,1],outputRange:[0,1,1,0]})}]} />;
}

function PassengerFlow({ active, color = '#f3c596', from, to, count = 4, spread = 160 }) {
  if(!active)return null;
  return <View pointerEvents="none" style={StyleSheet.absoluteFill}>{Array.from({length:count}).map((_,i)=><MovingDot key={i} delay={i*spread} duration={2500+(i%3)*300} color={i%3===0?color:i%3===1?'#e78762':'#6f82ae'} from={[from[0]+(i%2)*3,from[1]+(i%3)*2]} to={[to[0]+(i%2)*5,to[1]+(i%2)*3]} size={5+(i%2)}/>)}</View>;
}

function DoorPair({ open }) {
  const v=useRef(new Animated.Value(open?1:0)).current;
  useEffect(()=>{Animated.timing(v,{toValue:open?1:0,duration:380,easing:Easing.inOut(Easing.quad),useNativeDriver:true}).start();},[open,v]);
  return <View style={styles.doorPocket}><Animated.View style={[styles.doorLeaf,{transform:[{translateX:v.interpolate({inputRange:[0,1],outputRange:[0,-5]})}]}]}/><Animated.View style={[styles.doorLeaf,{right:0,transform:[{translateX:v.interpolate({inputRange:[0,1],outputRange:[0,5]})}]}]}/></View>;
}

function TrainGraphic({ service, top, pulse }) {
  const route=routeById(service.routeId);
  const sets=Math.max(1,Math.min(3,service.sets));
  const width=132+(sets-1)*55;
  const translate=useRef(new Animated.Value(service.phase==='arriving'?1:0)).current;
  const phaseRef=useRef(service.phase);

  useEffect(()=>{
    const prev=phaseRef.current;phaseRef.current=service.phase;
    if(service.phase==='arriving'){
      translate.setValue(1);
      Animated.timing(translate,{toValue:0,duration:1250,easing:Easing.out(Easing.cubic),useNativeDriver:true}).start();
    } else if(service.phase==='departing'){
      translate.setValue(0);
      Animated.timing(translate,{toValue:-1,duration:1450,easing:Easing.in(Easing.cubic),useNativeDriver:true}).start();
    } else if(prev==='away'&&service.phase==='boarding'){
      translate.setValue(0);
    }
  },[service.phase,translate]);

  if(service.phase==='away')return null;
  const ready=service.phase==='ready';
  const doorsOpen=service.phase==='boarding'||service.phase==='holding';
  const x=translate.interpolate({inputRange:[-1,0,1],outputRange:[-330,0,330]});
  const opacity=ready?pulse.interpolate({inputRange:[0,1],outputRange:[.78,1]}):1;
  return <Animated.View style={[styles.trainWrap,{top,width,opacity,transform:[{translateX:x},{rotateZ:'-2deg'}]}]}>
    <View style={[styles.trainShadow,{width:width-6}]}/>
    <View style={[styles.trainBody,{width,borderColor:ready?'#ffd362':'#cad6da'}]}>
      <View style={[styles.trainNose,{backgroundColor:route.color}]}/><View style={styles.cabGlass}/><View style={[styles.routeStripe,{backgroundColor:route.color}]}/>
      {Array.from({length:sets}).map((_,setIndex)=>{const baseLeft=34+setIndex*55;return <React.Fragment key={setIndex}><View style={[styles.carJoint,{left:baseLeft-2}]}/><View style={[styles.carWindow,{left:baseLeft+3}]}/><View style={[styles.carWindow,{left:baseLeft+18}]}/><View style={[styles.carWindow,{left:baseLeft+33}]}/><View style={[styles.doorSlot,{left:baseLeft+43}]}><DoorPair open={doorsOpen}/></View><View style={[styles.bogie,{left:baseLeft+5}]}/><View style={[styles.bogie,{left:baseLeft+32}]}/></React.Fragment>})}
      <View style={styles.trainRoofDetail}/>
      <View style={[styles.signalLamp,service.phase==='ready'&&styles.signalLampReady]}/>
    </View>
  </Animated.View>;
}

